"""sklearn.metrics.pairwise — pairwise distance / kernel functions.

Pure numpy implementations matching upstream's API."""

import numpy as _np


# Pairwise distance functions ─────────────────────────────────────


def euclidean_distances(X, Y=None, *, Y_norm_squared=None, squared=False,
                         X_norm_squared=None):
    """Pairwise Euclidean distance between rows of ``X`` and ``Y``."""
    X = _np.asarray(X)
    Y = X if Y is None else _np.asarray(Y)
    XX = (X ** 2).sum(axis=1) if X_norm_squared is None else _np.asarray(X_norm_squared)
    YY = (Y ** 2).sum(axis=1) if Y_norm_squared is None else _np.asarray(Y_norm_squared)
    XY = X @ Y.T
    distances = XX[:, None] + YY[None, :] - 2 * XY
    _np.maximum(distances, 0, out=distances)
    return distances if squared else _np.sqrt(distances)


def manhattan_distances(X, Y=None, *, sum_over_features=True):
    """Pairwise L1 distance."""
    X = _np.asarray(X)
    Y = X if Y is None else _np.asarray(Y)
    diff = _np.abs(X[:, None, :] - Y[None, :, :])
    return diff.sum(axis=-1) if sum_over_features else diff


def cosine_distances(X, Y=None):
    """1 - cosine_similarity."""
    return 1 - cosine_similarity(X, Y)


def haversine_distances(X, Y=None):
    """Great-circle distance between points on a sphere (radians)."""
    X = _np.asarray(X); Y = X if Y is None else _np.asarray(Y)
    lat1 = X[:, 0:1]; lon1 = X[:, 1:2]
    lat2 = Y[None, :, 0]; lon2 = Y[None, :, 1]
    dlat = lat2 - lat1; dlon = lon2 - lon1
    a = (_np.sin(dlat / 2) ** 2 +
         _np.cos(lat1) * _np.cos(lat2) * _np.sin(dlon / 2) ** 2)
    return 2 * _np.arcsin(_np.sqrt(a))


def nan_euclidean_distances(X, Y=None, *, squared=False,
                              missing_values=_np.nan, copy=True):
    """Euclidean distance ignoring NaN entries."""
    X = _np.asarray(X, dtype=float)
    Y = X.copy() if Y is None else _np.asarray(Y, dtype=float)
    mask_x = _np.isnan(X); mask_y = _np.isnan(Y)
    XX = _np.where(mask_x, 0, X)
    YY = _np.where(mask_y, 0, Y)
    distances = (XX[:, None, :] - YY[None, :, :]) ** 2
    distances = _np.where(mask_x[:, None, :] | mask_y[None, :, :], 0, distances)
    n_valid = (~(mask_x[:, None, :] | mask_y[None, :, :])).sum(axis=-1)
    out = distances.sum(axis=-1) * (X.shape[1] / _np.maximum(n_valid, 1))
    return out if squared else _np.sqrt(out)


def paired_distances(X, Y, *, metric='euclidean', **kwds):
    """Paired (not pairwise) distance — element i of X to element i of Y."""
    X = _np.asarray(X); Y = _np.asarray(Y)
    if metric == 'euclidean':
        return _np.linalg.norm(X - Y, axis=1)
    if metric == 'manhattan' or metric == 'cityblock':
        return _np.abs(X - Y).sum(axis=1)
    if metric == 'cosine':
        return 1 - (X * Y).sum(axis=1) / (_np.linalg.norm(X, axis=1) *
                                          _np.linalg.norm(Y, axis=1))
    raise ValueError(f'unknown metric: {metric!r}')


def paired_euclidean_distances(X, Y):
    return paired_distances(X, Y, metric='euclidean')


def paired_manhattan_distances(X, Y):
    return paired_distances(X, Y, metric='manhattan')


def paired_cosine_distances(X, Y):
    return paired_distances(X, Y, metric='cosine')


def pairwise_distances(X, Y=None, metric='euclidean', *, n_jobs=None,
                        force_all_finite=True, **kwds):
    """Generic pairwise-distance dispatcher."""
    if metric == 'euclidean':       return euclidean_distances(X, Y)
    if metric == 'manhattan' or metric == 'l1':
        return manhattan_distances(X, Y)
    if metric == 'cosine':          return cosine_distances(X, Y)
    if metric == 'haversine':       return haversine_distances(X, Y)
    if metric == 'nan_euclidean':   return nan_euclidean_distances(X, Y)
    if metric == 'minkowski':
        p = kwds.get('p', 2)
        X = _np.asarray(X); Y = X if Y is None else _np.asarray(Y)
        return (_np.abs(X[:, None, :] - Y[None, :, :]) ** p).sum(axis=-1) ** (1 / p)
    if callable(metric):
        X = _np.asarray(X); Y = X if Y is None else _np.asarray(Y)
        out = _np.zeros((len(X), len(Y)))
        for i, xi in enumerate(X):
            for j, yj in enumerate(Y):
                out[i, j] = metric(xi, yj, **kwds)
        return out
    raise ValueError(f'unknown metric: {metric!r}')


def pairwise_distances_argmin(X, Y, *, axis=1, metric='euclidean',
                                metric_kwargs=None):
    """Index of the nearest row in ``Y`` for every row in ``X``."""
    D = pairwise_distances(X, Y, metric=metric, **(metric_kwargs or {}))
    return _np.argmin(D, axis=axis)


def pairwise_distances_argmin_min(X, Y, *, axis=1, metric='euclidean',
                                    metric_kwargs=None):
    """``(argmin, min)`` of pairwise distances."""
    D = pairwise_distances(X, Y, metric=metric, **(metric_kwargs or {}))
    idx = _np.argmin(D, axis=axis)
    return idx, _np.min(D, axis=axis)


def pairwise_distances_chunked(X, Y=None, *, reduce_func=None, metric='euclidean',
                                 n_jobs=None, working_memory=None, **kwds):
    """Generator producing distance-matrix chunks. The shim yields the
    full matrix at once."""
    D = pairwise_distances(X, Y, metric=metric, **kwds)
    yield D if reduce_func is None else reduce_func(D, 0)


# Kernel functions ─────────────────────────────────────────────────


def linear_kernel(X, Y=None, *, dense_output=True):
    X = _np.asarray(X)
    Y = X if Y is None else _np.asarray(Y)
    return X @ Y.T


def polynomial_kernel(X, Y=None, *, degree=3, gamma=None, coef0=1):
    X = _np.asarray(X)
    Y = X if Y is None else _np.asarray(Y)
    if gamma is None: gamma = 1.0 / X.shape[1]
    return (gamma * (X @ Y.T) + coef0) ** degree


def rbf_kernel(X, Y=None, *, gamma=None):
    X = _np.asarray(X)
    Y = X if Y is None else _np.asarray(Y)
    if gamma is None: gamma = 1.0 / X.shape[1]
    return _np.exp(-gamma * euclidean_distances(X, Y, squared=True))


def laplacian_kernel(X, Y=None, *, gamma=None):
    X = _np.asarray(X)
    Y = X if Y is None else _np.asarray(Y)
    if gamma is None: gamma = 1.0 / X.shape[1]
    return _np.exp(-gamma * manhattan_distances(X, Y))


def sigmoid_kernel(X, Y=None, *, gamma=None, coef0=1):
    X = _np.asarray(X)
    Y = X if Y is None else _np.asarray(Y)
    if gamma is None: gamma = 1.0 / X.shape[1]
    return _np.tanh(gamma * (X @ Y.T) + coef0)


def cosine_similarity(X, Y=None, *, dense_output=True):
    X = _np.asarray(X, dtype=float)
    Y = X if Y is None else _np.asarray(Y, dtype=float)
    X_norm = _np.linalg.norm(X, axis=1, keepdims=True)
    Y_norm = _np.linalg.norm(Y, axis=1, keepdims=True)
    X_norm[X_norm == 0] = 1; Y_norm[Y_norm == 0] = 1
    return (X / X_norm) @ (Y / Y_norm).T


def chi2_kernel(X, Y=None, *, gamma=1.0):
    X = _np.asarray(X); Y = X if Y is None else _np.asarray(Y)
    K = _np.zeros((len(X), len(Y)))
    for i, xi in enumerate(X):
        for j, yj in enumerate(Y):
            num = (xi - yj) ** 2
            den = xi + yj + 1e-12
            K[i, j] = _np.exp(-gamma * (num / den).sum())
    return K


def additive_chi2_kernel(X, Y=None):
    X = _np.asarray(X); Y = X if Y is None else _np.asarray(Y)
    K = _np.zeros((len(X), len(Y)))
    for i, xi in enumerate(X):
        for j, yj in enumerate(Y):
            num = (xi - yj) ** 2
            den = xi + yj + 1e-12
            K[i, j] = -(num / den).sum()
    return K


def pairwise_kernels(X, Y=None, metric='linear', *, filter_params=False,
                      n_jobs=None, **kwds):
    """Dispatcher for kernel functions."""
    kernels = {
        'linear': linear_kernel, 'polynomial': polynomial_kernel,
        'poly': polynomial_kernel, 'rbf': rbf_kernel,
        'laplacian': laplacian_kernel, 'sigmoid': sigmoid_kernel,
        'cosine': cosine_similarity, 'chi2': chi2_kernel,
        'additive_chi2': additive_chi2_kernel,
    }
    if metric in kernels:
        return kernels[metric](X, Y, **kwds)
    if callable(metric):
        X = _np.asarray(X); Y = X if Y is None else _np.asarray(Y)
        out = _np.zeros((len(X), len(Y)))
        for i, xi in enumerate(X):
            for j, yj in enumerate(Y):
                out[i, j] = metric(xi, yj, **kwds)
        return out
    raise ValueError(f'unknown kernel: {metric!r}')


# Registry — upstream exposes these dicts of name → function.
PAIRWISE_DISTANCE_FUNCTIONS = {
    'euclidean': euclidean_distances, 'l2': euclidean_distances,
    'manhattan': manhattan_distances, 'l1': manhattan_distances,
    'cityblock': manhattan_distances, 'cosine': cosine_distances,
    'haversine': haversine_distances, 'nan_euclidean': nan_euclidean_distances,
}

PAIRWISE_KERNEL_FUNCTIONS = {
    'linear': linear_kernel, 'polynomial': polynomial_kernel,
    'poly': polynomial_kernel, 'rbf': rbf_kernel,
    'laplacian': laplacian_kernel, 'sigmoid': sigmoid_kernel,
    'cosine': cosine_similarity, 'chi2': chi2_kernel,
    'additive_chi2': additive_chi2_kernel,
}

# Pairwise-distance metric names (sorted, for completeness).
KERNEL_PARAMS = {
    'rbf': frozenset(['gamma']),
    'polynomial': frozenset(['degree', 'gamma', 'coef0']),
    'sigmoid': frozenset(['gamma', 'coef0']),
    'laplacian': frozenset(['gamma']),
    'chi2': frozenset(['gamma']),
    'additive_chi2': frozenset(),
    'linear': frozenset(),
    'cosine': frozenset(),
}

# Distance-metric short names for the BallTree / KDTree integrations.
distance_metrics = lambda: dict(PAIRWISE_DISTANCE_FUNCTIONS)


